    31	function hasExpensifyPaymentMethod(fundList: Record<string, Fund>, bankAccountList: Record<string, BankAccount>, shouldIncludeDebitCard = true): boolean {
    32	    const validBankAccount = Object.values(bankAccountList).some((bankAccountJSON) => {
    33	        const bankAccount = new BankAccountModel(bankAccountJSON);
    34	
    35	        return (
    36	            bankAccount.getPendingAction() !== CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE &&
    37	            bankAccount.isOpen() &&
    38	            bankAccount.getType() === CONST.BANK_ACCOUNT.TYPE.PERSONAL &&
    39	            bankAccount?.getCountry() === CONST.COUNTRY.US
    40	        );
    41	    });
    42	
    43	    // Hide any billing cards that are not P2P debit cards for now because you cannot make them your default method, or delete them
    44	    const validDebitCard = Object.values(fundList).some((card) => card?.accountData?.additionalData?.isP2PDebitCard ?? false);
    45	
    46	    return validBankAccount || (shouldIncludeDebitCard && validDebitCard);
    47	}
