    67	function formatPaymentMethods(bankAccountList: Record<string, BankAccount>, fundList: Record<string, Fund> | Fund[], styles: ThemeStyles): PaymentMethod[] {
    68	    const combinedPaymentMethods: PaymentMethod[] = [];
    69	
    70	    Object.values(bankAccountList).forEach((bankAccount) => {
    71	        // Add all bank accounts besides the wallet
    72	        if (bankAccount?.accountData?.type === CONST.BANK_ACCOUNT_TYPES.WALLET) {
