    74	        }
    75	
    76	        const {icon, iconSize, iconHeight, iconWidth, iconStyles} = getBankIcon({
    77	            bankName: bankAccount?.accountData?.additionalData?.bankName,
    78	            isCard: false,
    79	            styles,
    80	        });
    81	        combinedPaymentMethods.push({
    82	            ...bankAccount,
    83	            description: getPaymentMethodDescription(bankAccount?.accountType, bankAccount.accountData, bankAccount.bankCurrency),
    84	            icon,
    85	            iconSize,
    86	            iconHeight,
    87	            iconWidth,
    88	            iconStyles,
    89	        });
