    94	        combinedPaymentMethods.push({
    95	            ...card,
    96	            description: getPaymentMethodDescription(card?.accountType, card.accountData),
    97	            icon,
    98	            iconSize,
    99	            iconHeight,
   100	            iconWidth,
   101	            iconStyles,
   102	        });
   103	    });
   104	
   105	    return combinedPaymentMethods;
   106	}
