   115	/**
   116	 * Determines the appropriate payment action based on user validation and policy restrictions.
   117	 * It navigates users to verification pages if necessary, triggers KYC flows for specific payment methods,
   118	 * handles direct approvals, or proceeds with basic payment processing.
   119	 */
   120	const selectPaymentType = (
   121	    event: KYCFlowEvent,
   122	    iouPaymentType: PaymentMethodType,
   123	    triggerKYCFlow: TriggerKYCFlow,
   124	    policy: OnyxEntry<Policy>,
   125	    onPress: (paymentType?: PaymentMethodType, payAsBusiness?: boolean, methodID?: number, paymentMethod?: KYCPaymentMethod) => void,
   126	    isUserValidated?: boolean,
   127	    confirmApproval?: () => void,
   128	    iouReport?: OnyxEntry<Report>,
   129	) => {
   130	    if (policy && shouldRestrictUserBillableActions(policy.id)) {
   131	        Navigation.navigate(ROUTES.RESTRICTED_ACTION.getRoute(policy.id));
   132	        return;
   133	    }
   134	
   135	    if (iouPaymentType === CONST.IOU.PAYMENT_TYPE.EXPENSIFY || iouPaymentType === CONST.IOU.PAYMENT_TYPE.VBBA) {
   136	        if (!isUserValidated) {
   137	            Navigation.navigate(ROUTES.SETTINGS_CONTACT_METHOD_VERIFY_ACCOUNT.getRoute(Navigation.getActiveRoute()));
   138	            return;
