   145	    if (iouPaymentType === CONST.IOU.REPORT_ACTION_TYPE.APPROVE) {
   146	        if (confirmApproval) {
   147	            confirmApproval();
   148	        } else {
   149	            approveMoneyRequest(iouReport);
   150	        }
   151	        return;
   152	    }
   153	
   154	    onPress(iouPaymentType);
